import fc from "fast-check";
import {expect, it} from "vitest";
import {slugify} from "./slug.ts";

const titles = fc.oneof(
	fc.string({maxLength: 300}),
	fc.array(fc.constantFrom("a", "Z", "9", " ", "-", "é", "🪴", "\u0301"), {
		minLength: 81,
		maxLength: 300,
	}).map((characters) => characters.join("")),
);

it("retains the first 80 normalized characters and removes a final hyphen", () => {
	const cases: Array<[string, string]> = [
		["a".repeat(41), "a".repeat(41)],
		["a".repeat(79), "a".repeat(79)],
		["a".repeat(80), "a".repeat(80)],
		["a".repeat(80) + "b", "a".repeat(80)],
		["a".repeat(300), "a".repeat(80)],
		["a".repeat(79) + " next", "a".repeat(79)],
		["  " + "É".repeat(79) + "   NEXT!", "e".repeat(79)],
		[
			"A practical guide to growing tomatoes on small balconies through the summer months",
			"a-practical-guide-to-growing-tomatoes-on-small-balconies-through-the-summer-mont",
		],
	];
	for (const [title, expected] of cases) {
		expect(slugify(title)).toBe(expected);
	}
});

it("never produces more than 80 characters", () => {
	expect(slugify("a".repeat(300)).length).toBeLessThanOrEqual(80);
	fc.assert(
		fc.property(titles, (title) => {
			expect(slugify(title).length).toBeLessThanOrEqual(80);
		}),
		{seed: 1},
	);
});

